window.AUTH=window.AUTH||{};window.AUTH["17-1471"]={"d":"17-1471","id":"2018/17-1471","n":"Home Depot U.S.A., Inc. v. Jackson","briefs":[{"k":"petitioner","label":"Brief of petitioner Home Depot U.S.A., Inc.","date":"2018-11-09","url":"https://www.supremecourt.gov/DocketPDF/17/17-1471/71565/20181109114813457_17-1471%20ts.pdf","side":"pet","n":46},{"k":"respondent","label":"Brief of respondent George W. Jackson","date":"2018-12-10","url":"https://www.supremecourt.gov/DocketPDF/17/17-1471/74663/20181210150336134_17-1471bs.pdf","side":"res","n":66},{"k":"reply","label":"Reply of petitioner Home Depot U.S.A., Inc.","date":"2019-01-08","url":"https://www.supremecourt.gov/DocketPDF/17/17-1471/78675/20190108123134470_17-1471%20rb.pdf","side":"pet","n":59}],"opinion":"https://www.supremecourt.gov/opinions/18pdf/17-1471_e2p3.pdf","tr":true,"items":[{"t":"case","label":"Ali v. Fed. Bureau of Prisons","cite":"552 U.S. 214","y":2008,"id":"2007/06-9130","sc":1,"op":2,"sum":"The Court agreed with the 11th Circuit and, in a 5-4 majority opinion written by Justice Clarence Thomas, held that the use of the word \"any\" should be given its normal interpretation, encompassing all federal officers whether or not they were involved in enforcing customs or excise laws.","sumSrc":"Oyez","by":{"0":"35, 38","1":"38","2":"8"}},{"t":"case","label":"Am. Bus Ass’n v. Slater","cite":"231 F.3d 1","y":2000,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/231/1/","by":{"0":"35"}},{"t":"case","label":"Brooks v. Zabka","cite":"450 P.2d 653","y":1969,"court":"Colo.","url":"https://www.courtlistener.com/c/P.2d/450/653/","by":{"0":"35"}},{"t":"case","label":"Dart Cherokee Basin Operating Co. v. Owens","cite":"135 S. Ct. 547","y":2014,"id":"2014/13-719","sc":1,"op":1,"ar":3,"sum":"The Court ruled that a defendant seeking removal of a case to federal court is not required to provide evidence supporting federal jurisdiction in the notice of removal.","sumSrc":"Oyez","by":{"0":"6, 10, 41, 42","1":"11, 17, 59","2":"21, 22"}},{"t":"case","label":"First Bank v. DJL Props., LLC","cite":"598 F.3d 915","y":2010,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/598/915/","op":4,"ar":1,"by":{"0":"37, 38","1":"12, 34"}},{"t":"case","label":"Gaines v. Fuentes","cite":"92 U.S. 10","y":1876,"id":"scdb/1875-127","sc":1,"sum":"This is an action in form to annul an alleged will of Daniel Clark, the father of the plaintiff in error, dated on the 13th of July, 1813, and to recall the decree of the court by which it was probated. It was brought in the Second District Court for the Parish of Orleans, which, under the laws of Louisiana, is invested with jurisdiction over the estates of deceased persons, and of appointments necessary in the …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"27"}},{"t":"case","label":"Gross v. FBL Fin. Servs., Inc.","cite":"557 U.S. 167","y":2009,"id":"2008/08-441","sc":1,"sum":"The Court held that a plaintiff must show that age was the \"but-for\" cause for the defendant's action in an Age Discrimination in Employment Act claim.","sumSrc":"Oyez","by":{"0":"33"}},{"t":"case","label":"Hardt v. Reliance Standard Life Ins. Co.","cite":"560 U.S. 242","y":2010,"id":"2009/09-448","sc":1,"op":1,"sum":"The Court held that a party is entitled to attorneys' fees pursuant to Section 502(g)(1) of the Employee Retirement Income Security Act when an ERISA violation has occurred.","sumSrc":"Oyez","by":{"0":"33"}},{"t":"case","label":"Henson v. Santander Consumer USA Inc.","cite":"137 S. Ct. 1718","y":2017,"id":"2016/16-349","sc":1,"sum":"The Court determined that a party that purchases a debt and attempts to collect the debt for its own account is not a “debt collector” subject to the Fair Debt Collection Practices Act (FDCPA).","sumSrc":"Oyez","by":{"0":"35"}},{"t":"case","label":"Lee v. Chesapeake & Ohio Ry. Co.","cite":"260 U.S. 653","y":1923,"id":"scdb/1922-079","sc":1,"sum":"1. A case which, by virtue of the diverse citizenship of the parties, falls within the general jurisdiction of the District Courts as conferred by Jud. Code, § 24, is within the general jurisdiction of a District Court sitting in a State of which neither party is a citizen.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"31"}},{"t":"case","label":"Mississippi ex rel. Hood v. AU Optronics Corp.","cite":"571 U.S. 161","y":2014,"id":"2013/12-1036","sc":1,"op":1,"sum":"Interpreting CAFA consistently with Rule 20 where Congress used terms in a like manner in both provisions.","sumSrc":"opinion","by":{"0":"34"}},{"t":"case","label":"Palisades Collections LLC v. Shorts","cite":"552 F.3d 327","y":2008,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/552/327/","op":2,"by":{"0":"passim","1":"11, 41","2":"19"}},{"t":"case","label":"Shamrock Oil & Gas Corp. v. Sheets","cite":"313 U.S. 100","y":1941,"id":"scdb/1940-150","sc":1,"op":8,"sum":"1, Removability of suits from state to federal courts is determined by the federal removal statute, unaffected by local law.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"passim","1":"passim","2":"passim"}},{"t":"case","label":"Sheets v. Shamrock Oil & Gas Corp.","cite":"115 F.2d 880","y":1940,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/115/880/","by":{"0":"17"}},{"t":"case","label":"Tex. & Pac. Ry. Co. v. Cody","cite":"166 U.S. 606","y":1897,"id":"scdb/1896-166","sc":1,"sum":"The plaintiff in his declaration described himself as a resident in Texas, and the defendant as a railway company created and existing under the laws of Texas. ‘The railway company was in fact a corporation organized under and by virtue of acts of Congress, and in a petition for the removal of the action from a state court of Texas to the Federal court, set that forth as a ground for removal, and the petition was …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"31"}},{"t":"case","label":"Tri-State Water Treatment, Inc. v. Bauer","cite":"845 F.3d 350","y":2017,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/845/350/","sum":"Explaining that Shamrock Oil “established” the meaning of “the term ‘defendant’ ”.","sumSrc":"brief:0","by":{"0":"passim","1":"5","2":"23"}},{"t":"case","label":"United States v. Gonzales","cite":"520 U.S. 1","y":1997,"id":"1996/95-1605","sc":1,"op":1,"sum":"In a 7-to-2 decision delivered by Justice Sandra Day O'Connor, the Court announced \"[t]he plain language of (the law) forbids a district court to direct that a term of imprisonment under the statute run concurrently with any other term of imprisonment, whether state or federal.\".","sumSrc":"Oyez","by":{"0":"34, 35","2":"18"}},{"t":"case","label":"Westwood Apex v. Contreras","cite":"644 F.3d 799","y":2011,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/644/799/","op":1,"sum":"Noting that Shamrock Oil “established [the] meaning of ‘defendant’ in Chapter 89 of the Judicial Code”.","sumSrc":"brief:0","by":{"0":"passim"}},{"t":"const","label":"Article III, Section 2","clauses":[["cases-controversies","Cases or Controversies (Justiciability)"],["original-jurisdiction","Original and Appellate Jurisdiction"]],"text":"The judicial Power shall extend to all Cases, in Law and Equity, arising under this Constitution, the Laws of the United States, and Treaties made, or which shall be made, under their Authority;—to all Cases affecting Ambassadors, other public Ministers and Consuls;—to all Cases of admiralty and maritime Jurisdiction;—to Controversies to which the United States shall be a Party;—to Controversies between two or more States;— between a State and Citizens of another State,—between Citizens of different States,—between Citizens of the same State claiming Lands under Grants of different States, and between a State, or the Citizens thereof, and foreign States, Citizens or Subjects. In all Cases affecting Ambassadors, other public Ministers and Consuls, and those in which a State shall be Party, the supreme Court shall have original Jurisdiction. In all the other Cases before mentioned, the supreme Court shall have appellate Jurisdiction, both as to Law and Fact, with such Exceptions, and under such Regulations as the Congress shall make. The Trial of all Crimes, except in Cases of Impeachment, shall be by Jury; and such Trial shall be held in the State where the said Crimes shall have been committed; but when not committed within any State, the Trial shall be at such Place or Places as the Congress may by Law have directed.","by":{"0":"24"}},{"t":"law","label":"Pub. L. No. 109-2","url":"https://www.govinfo.gov/link/plaw/109/public/2","by":{"0":"4, 13, 32, 43","1":"39","2":"16, 21"}},{"t":"usc","label":"28 U.S.C. § 71","url":"https://www.law.cornell.edu/uscode/text/28/71","subs":["(1940)"],"by":{"0":"6, 18"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"0":"1"}},{"t":"usc","label":"28 U.S.C. § 1332","url":"https://www.law.cornell.edu/uscode/text/28/1332","subs":["(d)(2)(A)","(d)(2)","(d)(4)(A)","(d)(4)(B)","(d)","(d)(1)(B)","(d)(4)(A)(i)(II)","(d)(4)(A)(ii)","(d)(7)"],"stext":{"head":"§1332. Diversity of citizenship; amount in controversy; costs","paras":[[0,"(a) The district courts shall have original jurisdiction of all civil actions where the matter in controversy exceeds the sum or value of $75,000, exclusive of interest and costs, and is between—"],[1,"(1) citizens of different States;"],[1,"(2) citizens of a State and citizens or subjects of a foreign state, except that the district courts shall not have original jurisdiction under this subsection of an action between citizens of a State and citizens or subjects of a foreign state who are lawfully admitted for permanent residence in the United States and are domiciled in the same State;"],[1,"(3) citizens of different States and in which citizens or subjects of a foreign state are additional parties; and"],[1,"(4) a foreign state, defined in section 1603(a) of this title, as plaintiff and citizens of a State or of different States."],[0,"(b) Except when express provision therefor is otherwise made in a statute of the United States, where the plaintiff who files the case originally in the Federal courts is finally adjudged to be entitled to recover less than the sum or value of $75,000, computed without regard to any setoff or counterclaim to which the defendant may be adjudged to be entitled, and exclusive of interest and costs, the district court may deny costs to the plaintiff and, in addition, may impose costs on the plaintiff."],[0,"(c) For the purposes of this section and section 1441 of this title—"],[1,"(1) a corporation shall be deemed to be a citizen of every State and foreign state by which it has been incorporated and of the State or foreign state where it has its principal place of business, except that in any direct action against the insurer of a policy or contract of liability insurance, whether incorporated or unincorporated, to which action the insured is not joined as a party-defendant, such insurer shall be deemed a citizen of—"],[2,"(A) every State and foreign state of which the insured is a citizen;"],[2,"(B) every State and foreign state by which the insurer has been incorporated; and"],[2,"(C) the State or foreign state where the insurer has its principal place of business; and"],[1,"(2) the legal representative of the estate of a decedent shall be deemed to be a citizen only of the same State as the decedent, and the legal representative of an infant or incompetent shall be deemed to be a citizen only of the same State as the infant or incompetent."],[0,"(d)(1) In this subsection—"],[1,"(A) the term \"class\" means all of the class members in a class action;"],[1,"(B) the term \"class action\" means any civil action filed under rule 23 of the Federal Rules of Civil Procedure or similar State statute or rule of judicial procedure authorizing an action to be brought by 1 or more representative persons as a class action;"],[1,"(C) the term \"class certification order\" means an order issued by a court approving the treatment of some or all aspects of a civil action as a class action; and"],[1,"(D) the term \"class members\" means the persons (named or unnamed) who fall within the definition of the proposed or certified class in a class action."],[0,"(2) The district courts shall have original jurisdiction of any civil action in which the matter in controversy exceeds the sum or value of $5,000,000, exclusive of interest and costs, and is a class action in which—"],[1,"(A) any member of a class of plaintiffs is a citizen of a State different from any defendant;"],[1,"(B) any member of a class of plaintiffs is a foreign state or a citizen or subject of a foreign state and any defendant is a citizen of a State; or"],[1,"(C) any member of a class of plaintiffs is a citizen of a State and any defendant is a foreign state or a citizen or subject of a foreign state."],[0,"(3) A district court may, in the interests of justice and looking at the totality of the circumstances, decline to exercise jurisdiction under paragraph (2) over a class action in which greater than one-third but less than two-thirds of the members of all proposed plaintiff classes in the aggregate and the primary defendants are citizens of the State in which the action was originally filed based on consideration of—"],[1,"(A) whether the claims asserted involve matters of national or interstate interest;"],[1,"(B) whether the claims asserted will be governed by laws of the State in which the action was originally filed or by the laws of other States;"],[1,"(C) whether the class action has been pleaded in a manner that seeks to avoid Federal jurisdiction;"],[1,"(D) whether the action was brought in a forum with a distinct nexus with the class members, the alleged harm, or the defendants;"],[1,"(E) whether the number of citizens of the State in which the action was originally filed in all proposed plaintiff classes in the aggregate is substantially larger than the number of citizens from any other State, and the citizenship of the other members of the proposed class is dispersed among a substantial number of States; and"],[1,"(F) whether, during the 3-year period preceding the filing of that class action, 1 or more other class actions asserting the same or similar claims on behalf of the same or other persons have been filed."],[0,"(4) A district court shall decline to exercise jurisdiction under paragraph (2)—"],[1,"(A)(i) over a class action in which—"],[2,"(I) greater than two-thirds of the members of all proposed plaintiff classes in the aggregate are citizens of the State in which the action was originally filed;"],[2,"(II) at least 1 defendant is a defendant—"],[3,"(aa) from whom significant relief is sought by members of the plaintiff class;"],[3,"(bb) whose alleged conduct forms a significant basis for the claims asserted by the proposed plaintiff class; and"],[3,"(cc) who is a citizen of the State in which the action was originally filed; and"],[2,"(III) principal injuries resulting from the alleged conduct or any related conduct of each defendant were incurred in the State in which the action was originally filed; and"],[1,"(ii) during the 3-year period preceding the filing of that class action, no other class action has been filed asserting the same or similar factual allegations against any of the defendants on behalf of the same or other persons; or"],[1,"(B) two-thirds or more of the members of all proposed plaintiff classes in the aggregate, and the primary defendants, are citizens of the State in which the action was originally filed."],[0,"(5) Paragraphs (2) through (4) shall not apply to any class action in which—"],[1,"(A) the primary defendants are States, State officials, or other governmental entities against whom the district court may be foreclosed from ordering relief; or"],[1,"(B) the number of members of all proposed plaintiff classes in the aggregate is less than 100."],[0,"(6) In any class action, the claims of the individual class members shall be aggregated to determine whether the matter in controversy exceeds the sum or value of $5,000,000, exclusive of interest and costs."],[0,"(7) Citizenship of the members of the proposed plaintiff classes shall be determined for purposes of paragraphs (2) through (6) as of the date of filing of the complaint or amended complaint, or, if the case stated by the initial pleading is not subject to Federal jurisdiction, as of the date of service by plaintiffs of an amended pleading, motion, or other paper, indicating the existence of Federal jurisdiction."],[0,"(8) This subsection shall apply to any class action before or after the entry of a class certification order by the court with respect to that action."],[0,"(9) Paragraph (2) shall not apply to any class action that solely involves a claim—"],[1,"(A) concerning a covered security as defined under 16(f)(3) 1 of the Securities Act of 1933 (15 U.S.C. 78p(f)(3) 2) and section 28(f)(5)(E) of the Securities Exchange Act of 1934 (15 U.S.C. 78bb(f)(5)(E));"],[1,"(B) that relates to the internal affairs or governance of a corporation or other form of business enterprise and that arises under or by virtue of the laws of the State in which such corporation or business enterprise is incorporated or organized; or"],[1,"(C) that relates to the rights, duties (including fiduciary duties), and obligations relating to or created by or pursuant to any security (as defined under section 2(a)(1) of the Securities Act of 1933 (15 U.S.C. 77b(a)(1)) and the regulations issued thereunder)."],[0,"(10) For purposes of this subsection and section 1453, an unincorporated association shall be deemed to be a citizen of the State where it has its principal place of business and the State under whose laws it is organized."],[0,"(11)(A) For purposes of this subsection and section 1453, a mass action shall be deemed to be a class action removable under paragraphs (2) through (10) if it otherwise meets the provisions of those paragraphs."],[0,"(B)(i) As used in subparagraph (A), the term \"mass action\" means any civil action (except a civil action within the scope of section 1711(2)) in which monetary relief claims of 100 or more persons are proposed to be tried jointly on the ground that the plaintiffs' claims involve common questions of law or fact, except that jurisdiction shall exist only over those plaintiffs whose claims in a mass action satisfy the jurisdictional amount requirements under subsection (a)."],[0,"(ii) As used in subparagraph (A), the term \"mass action\" shall not include any civil action in which—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1332?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§1332. Diversity of citizenship; amount in controversy; costs","tname":"Judiciary and Judicial Procedure","by":{"0":"5, 5","1":"41, 46, 9, 41, 57, 58, 41","2":"11, 13, 20, 20, 17, 20, 20, 23, 23, 12"}},{"t":"usc","label":"28 U.S.C. § 1441","url":"https://www.law.cornell.edu/uscode/text/28/1441","subs":["(a)","(b)(2)","(c)"],"stext":{"head":"§1441. Removal of civil actions","paras":[[0,"(a) Generally.—Except as otherwise expressly provided by Act of Congress, any civil action brought in a State court of which the district courts of the United States have original jurisdiction, may be removed by the defendant or the defendants, to the district court of the United States for the district and division embracing the place where such action is pending."],[0,"(b) Removal Based on Diversity of Citizenship.—(1) In determining whether a civil action is removable on the basis of the jurisdiction under section 1332(a) of this title, the citizenship of defendants sued under fictitious names shall be disregarded."],[0,"(2) A civil action otherwise removable solely on the basis of the jurisdiction under section 1332(a) of this title may not be removed if any of the parties in interest properly joined and served as defendants is a citizen of the State in which such action is brought."],[0,"(c) Joinder of Federal Law Claims and State Law Claims.—(1) If a civil action includes—"],[1,"(A) a claim arising under the Constitution, laws, or treaties of the United States (within the meaning of section 1331 of this title), and"],[1,"(B) a claim not within the original or supplemental jurisdiction of the district court or a claim that has been made nonremovable by statute,"],[0,"the entire action may be removed if the action would be removable without the inclusion of the claim described in subparagraph (B)."],[0,"(2) Upon removal of an action described in paragraph (1), the district court shall sever from the action all claims described in paragraph (1)(B) and shall remand the severed claims to the State court from which the action was removed. Only defendants against whom a claim described in paragraph (1)(A) has been asserted are required to join in or consent to the removal under paragraph (1)."],[0,"(d) Actions Against Foreign States.—Any civil action brought in a State court against a foreign state as defined in section 1603(a) of this title may be removed by the foreign state to the district court of the United States for the district and division embracing the place where such action is pending. Upon removal the action shall be tried by the court without jury. Where removal is based upon this subsection, the time limitations of section 1446(b) of this chapter may be enlarged at any time for cause shown."],[0,"(e) Multiparty, Multiforum Jurisdiction.—(1) Notwithstanding the provisions of subsection (b) of this section, a defendant in a civil action in a State court may remove the action to the district court of the United States for the district and division embracing the place where the action is pending if—"],[1,"(A) the action could have been brought in a United States district court under section 1369 of this title; or"],[1,"(B) the defendant is a party to an action which is or could have been brought, in whole or in part, under section 1369 in a United States district court and arises from the same accident as the action in State court, even if the action to be removed could not have been brought in a district court as an original matter."],[0,"The removal of an action under this subsection shall be made in accordance with section 1446 of this title, except that a notice of removal may also be filed before trial of the action in State court within 30 days after the date on which the defendant first becomes a party to an action under section 1369 in a United States district court that arises from the same accident as the action in State court, or at a later time with leave of the district court."],[0,"(2) Whenever an action is removed under this subsection and the district court to which it is removed or transferred under section 1407(j) 1 has made a liability determination requiring further proceedings as to damages, the district court shall remand the action to the State court from which it had been removed for the determination of damages, unless the court finds that, for the convenience of parties and witnesses and in the interest of justice, the action should be retained for the determination of damages."],[0,"(3) Any remand under paragraph (2) shall not be effective until 60 days after the district court has issued an order determining liability and has certified its intention to remand the removed action for the determination of damages. An appeal with respect to the liability determination of the district court may be taken during that 60-day period to the court of appeals with appellate jurisdiction over the district court. In the event a party files such an appeal, the remand shall not be effective until the appeal has been finally disposed of. Once the remand has become effective, the liability determination shall not be subject to further review by appeal or otherwise."],[0,"(4) Any decision under this subsection concerning remand for the determination of damages shall not be reviewable by appeal or otherwise."],[0,"(5) An action removed under this subsection shall be deemed to be an action under section 1369 and an action in which jurisdiction is based on section 1369 of this title for purposes of this section and sections 1407, 1697, and 1785 of this title."],[0,"(6) Nothing in this subsection shall restrict the authority of the district court to transfer or dismiss an action on the ground of inconvenient forum."],[0,"(f) Derivative Removal Jurisdiction.—The court to which a civil action is removed under this section is not precluded from hearing and determining any claim in such civil action because the State court from which such civil action is removed did not have jurisdiction over that claim."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1441?type=usc&year=mostrecent&link-type=html"},"op":47,"head":"§1441. Removal of civil actions","tname":"Judiciary and Judicial Procedure","by":{"0":"passim, passim, 3, 4, 28","1":"passim, 28","2":"11, 14, passim, 4, 11, 12, 14"}},{"t":"usc","label":"28 U.S.C. § 1446","url":"https://www.law.cornell.edu/uscode/text/28/1446","subs":["(a)","(b)","(b)(1)","(b)(2)(A)","(b)(2)(B)","(b)(2)(C)","(b)(3)","(c)(1)"],"stext":{"head":"§1446. Procedure for removal of civil actions","paras":[[0,"(a) Generally.—A defendant or defendants desiring to remove any civil action from a State court shall file in the district court of the United States for the district and division within which such action is pending a notice of removal signed pursuant to Rule 11 of the Federal Rules of Civil Procedure and containing a short and plain statement of the grounds for removal, together with a copy of all process, pleadings, and orders served upon such defendant or defendants in such action."],[0,"(b) Requirements; Generally.—(1) The notice of removal of a civil action or proceeding shall be filed within 30 days after the receipt by the defendant, through service or otherwise, of a copy of the initial pleading setting forth the claim for relief upon which such action or proceeding is based, or within 30 days after the service of summons upon the defendant if such initial pleading has then been filed in court and is not required to be served on the defendant, whichever period is shorter."],[0,"(2)(A) When a civil action is removed solely under section 1441(a), all defendants who have been properly joined and served must join in or consent to the removal of the action."],[0,"(B) Each defendant shall have 30 days after receipt by or service on that defendant of the initial pleading or summons described in paragraph (1) to file the notice of removal."],[0,"(C) If defendants are served at different times, and a later-served defendant files a notice of removal, any earlier-served defendant may consent to the removal even though that earlier-served defendant did not previously initiate or consent to removal."],[0,"(3) Except as provided in subsection (c), if the case stated by the initial pleading is not removable, a notice of removal may be filed within thirty days after receipt by the defendant, through service or otherwise, of a copy of an amended pleading, motion, order or other paper from which it may first be ascertained that the case is one which is or has become removable."],[0,"(c) Requirements; Removal Based on Diversity of Citizenship.—(1) A case may not be removed under subsection (b)(3) on the basis of jurisdiction conferred by section 1332 more than 1 year after commencement of the action, unless the district court finds that the plaintiff has acted in bad faith in order to prevent a defendant from removing the action."],[0,"(2) If removal of a civil action is sought on the basis of the jurisdiction conferred by section 1332(a), the sum demanded in good faith in the initial pleading shall be deemed to be the amount in controversy, except that—"],[1,"(A) the notice of removal may assert the amount in controversy if the initial pleading seeks—"],[2,"(i) nonmonetary relief; or"],[2,"(ii) a money judgment, but the State practice either does not permit demand for a specific sum or permits recovery of damages in excess of the amount demanded; and"],[1,"(B) removal of the action is proper on the basis of an amount in controversy asserted under subparagraph (A) if the district court finds, by the preponderance of the evidence, that the amount in controversy exceeds the amount specified in section 1332(a)."],[0,"(3)(A) If the case stated by the initial pleading is not removable solely because the amount in controversy does not exceed the amount specified in section 1332(a), information relating to the amount in controversy in the record of the State proceeding, or in responses to discovery, shall be treated as an \"other paper\" under subsection (b)(3)."],[0,"(B) If the notice of removal is filed more than 1 year after commencement of the action and the district court finds that the plaintiff deliberately failed to disclose the actual amount in controversy to prevent removal, that finding shall be deemed bad faith under paragraph (1)."],[0,"(d) Notice to Adverse Parties and State Court.—Promptly after the filing of such notice of removal of a civil action the defendant or defendants shall give written notice thereof to all adverse parties and shall file a copy of the notice with the clerk of such State court, which shall effect the removal and the State court shall proceed no further unless and until the case is remanded."],[0,"(e) Counterclaim in 337 Proceeding.—With respect to any counterclaim removed to a district court pursuant to section 337(c) of the Tariff Act of 1930, the district court shall resolve such counterclaim in the same manner as an original complaint under the Federal Rules of Civil Procedure, except that the payment of a filing fee shall not be required in such cases and the counterclaim shall relate back to the date of the original complaint in the proceeding before the International Trade Commission under section 337 of that Act."],[0,"(g) 1 Where the civil action or criminal prosecution that is removable under section 1442(a) is a proceeding in which a judicial order for testimony or documents is sought or issued or sought to be enforced, the 30-day requirement of subsection (b) of this section and paragraph (1) of section 1455(b) is satisfied if the person or entity desiring to remove the proceeding files the notice of removal not later than 30 days after receiving, through service, notice of any such proceeding."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1446?type=usc&year=mostrecent&link-type=html"},"op":3,"ar":1,"head":"§1446. Procedure for removal of civil actions","tname":"Judiciary and Judicial Procedure","by":{"0":"passim, 39, 39, 40, 4, 4, 22, 22, 4, 21, 22, 4, 4","1":"30","2":"12, 18, 12"}},{"t":"usc","label":"28 U.S.C. § 1453","url":"https://www.law.cornell.edu/uscode/text/28/1453","subs":["(b)","(c)","(c)(2)","(a)","(c)(3)","(c)(4)"],"stext":{"head":"§1453. Removal of class actions","paras":[[0,"(a) Definitions.—In this section, the terms \"class\", \"class action\", \"class certification order\", and \"class member\" shall have the meanings given such terms under section 1332(d)(1)."],[0,"(b) In General.—A class action may be removed to a district court of the United States in accordance with section 1446 (except that the 1-year limitation under section 1446(c)(1) shall not apply), without regard to whether any defendant is a citizen of the State in which the action is brought, except that such action may be removed by any defendant without the consent of all defendants."],[0,"(c) Review of Remand Orders.—"],[1,"(1) In general.—Section 1447 shall apply to any removal of a case under this section, except that notwithstanding section 1447(d), a court of appeals may accept an appeal from an order of a district court granting or denying a motion to remand a class action to the State court from which it was removed if application is made to the court of appeals not more than 10 days after entry of the order."],[1,"(2) Time period for judgment.—If the court of appeals accepts an appeal under paragraph (1), the court shall complete all action on such appeal, including rendering judgment, not later than 60 days after the date on which such appeal was filed, unless an extension is granted under paragraph (3)."],[1,"(3) Extension of time period.—The court of appeals may grant an extension of the 60-day period described in paragraph (2) if—"],[2,"(A) all parties to the proceeding agree to such extension, for any period of time; or"],[2,"(B) such extension is for good cause shown and in the interests of justice, for a period not to exceed 10 days."],[1,"(4) Denial of appeal.—If a final judgment on the appeal under paragraph (1) is not issued before the end of the period described in paragraph (2), including any extension under paragraph (3), the appeal shall be denied."],[0,"(d) Exception.—This section shall not apply to any class action that solely involves—"],[1,"(1) a claim concerning a covered security as defined under section 16(f)(3) of the Securities Act of 1933 (15 U.S.C. 78p(f)(3) 1) and section 28(f)(5)(E) of the Securities Exchange Act of 1934 (15 U.S.C. 78bb(f)(5)(E));"],[1,"(2) a claim that relates to the internal affairs or governance of a corporation or other form of business enterprise and arises under or by virtue of the laws of the State in which such corporation or business enterprise is incorporated or organized; or"],[1,"(3) a claim that relates to the rights, duties (including fiduciary duties), and obligations relating to or created by or pursuant to any security (as defined under section 2(a)(1) of the Securities Act of 1933 (15 U.S.C. 77b(a)(1)) and the regulations issued thereunder)."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1453?type=usc&year=mostrecent&link-type=html"},"op":4,"ar":1,"head":"§1453. Removal of class actions","tname":"Judiciary and Judicial Procedure","by":{"0":"5, 6, passim","1":"15, 37, 42, 59, 57","2":"20, 20, passim, 22, 22, 22"}},{"t":"usc","label":"28 U.S.C. § 1711","url":"https://www.law.cornell.edu/uscode/text/28/1711","by":{"0":"43"}},{"t":"rule","label":"Fed. R. Civ. P. 12","url":"https://www.law.cornell.edu/rules/frcp/rule_12","subs":["(a)(1)(A)","(a)(1)(B)","(a)(1)"],"by":{"0":"34, 38","1":"26, 26","2":"10"}},{"t":"rule","label":"Fed. R. Civ. P. 13","url":"https://www.law.cornell.edu/rules/frcp/rule_13","subs":["(h)"],"by":{"0":"16, 16, 38","1":"26","2":"17"}},{"t":"rule","label":"Fed. R. Civ. P. 14","url":"https://www.law.cornell.edu/rules/frcp/rule_14","subs":["(a)(1)"],"by":{"0":"16","2":"1"}},{"t":"rule","label":"Fed. R. Civ. P. 20","url":"https://www.law.cornell.edu/rules/frcp/rule_20","subs":["(a)(2)(A)"],"by":{"0":"34"}},{"t":"case","label":"Abrego Abrego v. Dow Chem. Co.","cite":"443 F.3d 676","y":2006,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/443/676/","by":{"1":"43"}},{"t":"case","label":"Am. Fire & Casualty Co. v. Finn","cite":"341 U.S. 6","y":1951,"id":"scdb/1950-055","sc":1,"op":1,"sum":"In a suit brought in a Texas court by a resident of that State to recover for a loss by fire, the complaint named as defendants two foreign insurance companies (one of which is the petitioner here) and a resident agent of the companies. The single wrong for which relief was sought was the failure to compensate for the loss, and the three defendants were joined because of uncertainty as to who was liable. After …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"36"}},{"t":"case","label":"Bank of New York Mellon v. Cioffi","cite":"2016 WL 3962818","y":2016,"court":"D. Mass. July 21","by":{"1":"25"}},{"t":"case","label":"Beneficial Nat’l Bank v. Anderson","cite":"539 U.S. 1","y":2003,"id":"2002/02-306","sc":1,"sum":"The Court held that the National Bank Act preempted the state-law claim and provided the exclusive cause of action for usury claims against national banks. Thus, the claim arose under federal law.","sumSrc":"Oyez","by":{"1":"23"}},{"t":"case","label":"BJB Co. v. Comp Air Leroi","cite":"148 F. Supp. 2d 751","y":2001,"court":"N.D. Tex.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/148/751/","by":{"1":"25"}},{"t":"case","label":"Brooks v. Rogers","cite":"346 S.E.2d 677","y":1986,"court":"N.C. App.","url":"https://www.courtlistener.com/c/S.E.2d/346/677/","by":{"1":"54"}},{"t":"case","label":"Cannon v. Univ. of Chicago","cite":"441 U.S. 677","y":1979,"id":"1978/77-926","sc":1,"sum":"Petitioner may maintain her lawsuit, despite the absence of any express authorization for it in Title IX.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"43"}},{"t":"case","label":"Carey v. Bank of Am., N.A.","cite":"904 F. Supp. 2d 617","y":2012,"court":"N.D. Tex.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/904/617/","by":{"1":"28"}},{"t":"case","label":"City of Indianapolis v. Chase Nat’l Bank","cite":"314 U.S. 63","y":1941,"id":"scdb/1941-007","sc":1,"ar":1,"sum":"1. To sustain federal jurisdiction on the ground of diversity of citizenship, there must exist an actual, substantial controversy, on one side of which the parties must all be citizens of States different from those of which the parties on the other side are citizens.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"18"}},{"t":"case","label":"Clark v. Martinez","cite":"543 U.S. 371","y":2005,"id":"2004/03-878","sc":1,"sum":"The Court said the requirement that immigrants be detained no longer than reasonably necessary for deportation applied to both admissible and inadmissible immigrants. Because readmission to Cuba was unforeseeable, the detentions of Martinez and Benitez were unreasonable.","sumSrc":"Oyez","by":{"1":"51"}},{"t":"case","label":"E.P.A. v. EME Homer City Generation, L.P.","cite":"572 U.S. 489","y":2014,"id":"2013/12-1182","sc":1,"sum":"The Court held that the EPA has an absolute mandate to require states to meet federal standards set forth in the Clean Air Act.","sumSrc":"Oyez","by":{"1":"38"}},{"t":"case","label":"Exxon Mobil Corp. v. Allapattah Servs., Inc.","cite":"545 U.S. 546","y":2005,"id":"2004/04-70","sc":1,"op":2,"ar":3,"sum":"The Court ruled that as long one plaintiff meets the amount-in-controversy requirement for federal jurisdiction, Section 1367 authorizes federal courts to exercise supplemental jurisdiction over related claims even if they do not meet the requirement.","sumSrc":"Oyez","by":{"1":"51","2":"11"}},{"t":"case","label":"Fiblenski v. Hirschback Motor Lines, Inc.","cite":"304 F. Supp. 283","y":1969,"court":"E.D. Ark.","url":"https://www.courtlistener.com/c/F.%20Supp./304/283/","by":{"1":"24, 35"}},{"t":"case","label":"Foltz v. Columbia Casualty Co.","cite":"2016 WL 3829144","y":2016,"court":"W.D. Okla. July 12","by":{"1":"47"}},{"t":"case","label":"Franchise Tax Bd. of Cal. v. Constr. Laborers Vacation Tr. for S. Cal.","cite":"463 U.S. 1","y":1983,"id":"1982/82-695","sc":1,"op":1,"sum":"The case is not within the removal jurisdiction conferred by 28 U. S. C. § 1441.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"23","2":"13"}},{"t":"case","label":"Gunn v. Minton","cite":"568 U.S. 251","y":2013,"id":"2012/11-1118","sc":1,"op":1,"sum":"The Court found that even though federal courts have exclusive jurisdiction over patent law cases, state courts can still hear cases related to patent law as long as that it is not the primary issue.","sumSrc":"Oyez","by":{"1":"51"}},{"t":"case","label":"H&H Terminals LC v. Ramos Family Tr., LLP","cite":"634 F. Supp. 2d 770","y":2009,"court":"W.D. Tex.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/634/770/","by":{"1":"48"}},{"t":"case","label":"Hart v. Knockerball MidMo, LLC","cite":"2018 WL 4997650","y":2018,"court":"W.D. Mo. Oct. 15","by":{"1":"55"}},{"t":"case","label":"Holmes Grp., Inc. v. Vornado Air Circulation Sys., Inc.","cite":"535 U.S. 826","y":2002,"id":"2001/01-408","sc":1,"op":5,"ar":1,"sum":"The Court held that the appellate could not assert jurisdiction over such a case.","sumSrc":"Oyez","by":{"1":"23","2":"13"}},{"t":"case","label":"Lead I JV, LP v. N. Fork Bank","cite":"401 B.R. 571","y":2009,"court":"E.D.N.Y.","url":"https://www.courtlistener.com/c/B.R./401/571/","sum":"Explaining that the statute’s reference to removal of a “claim or cause of action” indicates that some claims may be removed without others.","sumSrc":"brief:1","by":{"1":"31"}},{"t":"case","label":"Lewis v. Windsor Door Co.","cite":"926 F.2d 729","y":1991,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.2d/926/729/","by":{"1":"35-36"}},{"t":"case","label":"Mach v. Triple D Supply, LLC","cite":"773 F. Supp. 2d 1018","y":2011,"court":"D.N.M.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/773/1018/","by":{"1":"25"}},{"t":"case","label":"Mexican Nat’l R.R. Co. v. Davidson","cite":"157 U.S. 201","y":1895,"id":"scdb/1894-149","sc":1,"op":1,"ar":1,"sum":"Under § 2 of the act of March 3,1887, c. 373, 24 Stat. 552, as corrected by the act of August 13, 1888, c. 866, 25 Stat. 433, the jurisdiction of a Circuit Court of the United States, on removal by the defendant of an action from a state court, is limited to such suits as might have been brought in that court under the first section.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"22, 23"}},{"t":"case","label":"Puerto Rico v. Franklin Cal. Tax-Free Tr.","cite":"136 S. Ct. 1938","y":2016,"id":"2015/15-233","sc":1,"sum":"The Court determined that Chapter 9 of the Bankruptcy Code preempted the Puerto Rico statute that allowed public utilities to restructure their debt.","sumSrc":"Oyez","by":{"1":"38"}},{"t":"case","label":"Share v. Sears, Roebuck & Co.","cite":"550 F. Supp. 1107","y":1982,"court":"E.D. Pa.","url":"https://www.courtlistener.com/c/F.%20Supp./550/1107/","by":{"1":"24-25, 35"}},{"t":"case","label":"Small v. United States","cite":"544 U.S. 385","y":2005,"id":"2004/03-750","sc":1,"op":4,"sum":"The Court held that the federal law's phrase, \"convicted in any court,\" encompassed only domestic, not foreign, convictions. The majority reasoned that in determining the scope of the phrase, it was appropriate to assume Congress had domestic concerns in mind. Moreover, the statute's overall language suggested no intent to reach beyond domestic convictions.","sumSrc":"Oyez","by":{"1":"38"}},{"t":"case","label":"State of Tennessee v. Union & Planters’ Bank","cite":"152 U.S. 454","y":1894,"id":"scdb/1893-185","sc":1,"op":1,"sum":"Under the act of August 13, 1888, c. 866, the Circuit Court of the United States has no jurisdiction, either original, or by removal-from a state court, of a suit as one arising under the Constitution, laws or treaties of the United States, unless that appears by the plaintiff’s statement of his own claim.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"22, 23"}},{"t":"case","label":"United States v. Palmer","cite":"16 U.S. 610","y":1818,"id":"scdb/1818-038","sc":1,"op":1,"sum":"A robbcry committed on the high seas, although such robbery if com., milled on land would not by the lav s of the United Surtes bo punishable with death, is piracy under the 8th section of the act of 1700 ch. 36, (ix) for the punishment of certain crimes against the United Slates; and the circuit court have jurisdiction thereof.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"38"}},{"t":"case","label":"Vaden v. Discover Bank","cite":"556 U.S. 49","y":2009,"id":"2008/07-773","sc":1,"sum":"The Court held that a federal court may \"look through\" a Section 4 petition to determine whether the claim establishes federal subject matter jurisdiction.","sumSrc":"Oyez","by":{"1":"23","2":"13"}},{"t":"case","label":"Vermont v. MPHJ Tech. Invs., LLC","cite":"803 F.3d 635","y":2015,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/803/635/","by":{"1":"31, 47"}},{"t":"case","label":"Wells Fargo Fin. S.C., Inc. v. Mack","cite":"2018 WL 3687978","y":2018,"court":"D.S.C. July 13","by":{"1":"55"}},{"t":"case","label":"White v. Baltic Conveyor Co.","cite":"209 F. Supp. 716","y":1962,"court":"D.N.J.","url":"https://www.courtlistener.com/c/F.%20Supp./209/716/","by":{"1":"24, 35"}},{"t":"case","label":"Whitman v. Am. Trucking Ass’ns","cite":"531 U.S. 457","y":2001,"id":"2000/99-1257","sc":1,"sum":"The Court held that the CAA properly delegated legislative power to the EPA, but that the EPA could not consider implementation costs in setting primary and secondary NAAQS.","sumSrc":"Oyez","by":{"1":"37","2":"18"}},{"t":"const","label":"Article III","clauses":[["judicial-vesting","Judicial Vesting Clause"],["cases-controversies","Cases or Controversies (Justiciability)"],["original-jurisdiction","Original and Appellate Jurisdiction"],["treason","Treason Clause"]],"by":{"1":"51"}},{"t":"usc","label":"15 U.S.C. § 16","url":"https://www.law.cornell.edu/uscode/text/15/16","subs":["(a)"],"by":{"1":"48"}},{"t":"usc","label":"15 U.S.C. § 78u-4","url":"https://www.law.cornell.edu/uscode/text/15/78u-4","subs":["(a)(8)"],"by":{"1":"48"}},{"t":"usc","label":"28 U.S.C. § 1391","url":"https://www.law.cornell.edu/uscode/text/28/1391","subs":["(b)(1)"],"by":{"1":"48"}},{"t":"usc","label":"28 U.S.C. § 1448","url":"https://www.law.cornell.edu/uscode/text/28/1448","by":{"1":"47"}},{"t":"usc","label":"28 U.S.C. § 1452","url":"https://www.law.cornell.edu/uscode/text/28/1452","subs":["(a)"],"by":{"1":"31, 52"}},{"t":"usc","label":"28 U.S.C. § 1454","url":"https://www.law.cornell.edu/uscode/text/28/1454","subs":["(a)","(b)(1)"],"stext":{"head":"§1454. Patent, plant variety protection, and copyright cases","paras":[[0,"(a) In General.—A civil action in which any party asserts a claim for relief arising under any Act of Congress relating to patents, plant variety protection, or copyrights may be removed to the district court of the United States for the district and division embracing the place where the action is pending."],[0,"(b) Special Rules.—The removal of an action under this section shall be made in accordance with section 1446, except that if the removal is based solely on this section—"],[1,"(1) the action may be removed by any party; and"],[1,"(2) the time limitations contained in section 1446(b) may be extended at any time for cause shown."],[0,"(c) Clarification of Jurisdiction in Certain Cases.—The court to which a civil action is removed under this section is not precluded from hearing and determining any claim in the civil action because the State court from which the civil action is removed did not have jurisdiction over that claim."],[0,"(d) Remand.—If a civil action is removed solely under this section, the district court—"],[1,"(1) shall remand all claims that are neither a basis for removal under subsection (a) nor within the original or supplemental jurisdiction of the district court under any Act of Congress; and"],[1,"(2) may, under the circumstances specified in section 1367(c), remand any claims within the supplemental jurisdiction of the district court under section 1367."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1454?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1454. Patent, plant variety protection, and copyright cases","tname":"Judiciary and Judicial Procedure","by":{"1":"31, 52, 47"}},{"t":"usc","label":"28 U.S.C. § 4103","url":"https://www.law.cornell.edu/uscode/text/28/4103","by":{"1":"46"}},{"t":"usc","label":"35 U.S.C. § 299","url":"https://www.law.cornell.edu/uscode/text/35/299","stext":{"head":"§299. Joinder of parties","paras":[[0,"(a) Joinder of Accused Infringers.—With respect to any civil action arising under any Act of Congress relating to patents, other than an action or trial in which an act of infringement under section 271(e)(2) has been pled, parties that are accused infringers may be joined in one action as defendants or counterclaim defendants, or have their actions consolidated for trial, only if—"],[1,"(1) any right to relief is asserted against the parties jointly, severally, or in the alternative with respect to or arising out of the same transaction, occurrence, or series of transactions or occurrences relating to the making, using, importing into the United States, offering for sale, or selling of the same accused product or process; and"],[1,"(2) questions of fact common to all defendants or counterclaim defendants will arise in the action."],[0,"(b) Allegations Insufficient for Joinder.—For purposes of this subsection, accused infringers may not be joined in one action as defendants or counterclaim defendants, or have their actions consolidated for trial, based solely on allegations that they each have infringed the patent or patents in suit."],[0,"(c) Waiver.—A party that is an accused infringer may waive the limitations set forth in this section with respect to that party."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/35/299?type=usc&year=mostrecent&link-type=html"},"head":"§299. Joinder of parties","tname":"Patents","by":{"1":"27, 47","2":"9"}},{"t":"usc","label":"42 U.S.C. § 1997","url":"https://www.law.cornell.edu/uscode/text/42/1997","by":{"1":"48"}},{"t":"law","label":"Pub. L. No. 112-63","url":"https://www.govinfo.gov/link/plaw/112/public/63","by":{"1":"27"}},{"t":"law","label":"Securing the Protection of our Enduring and Established Constitutional Heritage Act, Pub. L. No. 111-223","url":"https://www.govinfo.gov/link/plaw/111/public/223","by":{"1":"46"}},{"t":"rule","label":"Fed. R. Civ. P. 30","url":"https://www.law.cornell.edu/rules/frcp/rule_30","subs":["(a)(2)(A)(i)"],"by":{"1":"26","2":"8, 8"}},{"t":"case","label":"Carl Heck Eng’rs, Inc. v. Lafourche Par. Police Jury","cite":"622 F.2d 133","y":1980,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/622/133/","op":3,"by":{"2":"12, 14"}},{"t":"case","label":"Caterpillar Inc. v. Williams","cite":"482 U.S. 386","y":1987,"id":"1986/86-526","sc":1,"op":1,"sum":"Respondents' state-law complaint for breach of the individual employment contracts is not removable to Federal District Court.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"14"}},{"t":"case","label":"Cent. of Ga. Ry. Co. v. Riegel Textile Corp.","cite":"426 F.2d 935","y":1970,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/426/935/","by":{"2":"15"}},{"t":"case","label":"Chi., Rock Island & Pac. Ry. Co. v. Martin","cite":"178 U.S. 245","y":1900,"id":"scdb/1899-057","sc":1,"sum":"This was an ordinary action, under a state statute, for wrongfully causing the death of plaintiff’s intestate, in which no Federal question was presented by the pleadings, or litigated at the trial, and in which the liability depended upon principles of general law, and not in any way upon the terms of the order appointing the receivers; and whatever the rights of the receivers might have been to remove the cause if …","sumSrc":"Headnote (U.S. Reports)","by":{"2":"18, 19"}},{"t":"case","label":"City of Chicago v. Int’l College of Surgeons","cite":"522 U.S. 156","y":1997,"id":"1997/96-910","sc":1,"sum":"The Court held that a case containing claims that local administrative action violates federal law, but also containing state law claims for on-the-record review of the administrative findings, can be removed to federal district court.","sumSrc":"Oyez","by":{"2":"11"}},{"t":"case","label":"Freeman v. Bee Mach. Co.","cite":"319 U.S. 448","y":1943,"id":"scdb/1942-091","sc":1,"op":1,"sum":"that the defendant was \"found\" within the district so as to give the District Court power to allow the complaint to be amended by adding a cause of action under § 4 of the Clayton Act.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"11"}},{"t":"case","label":"Halliburton Co. v. Erica P. John Fund, Inc.","cite":"573 U.S. 258","y":2014,"id":"2013/13-317","sc":1,"op":1,"sum":"The Court held that there is no undue burden in allowing defendants in securities fraud cases from presenting evidence regarding the alleged impact of the misinformation on stock prices.","sumSrc":"Oyez","by":{"2":"15"}},{"t":"case","label":"Healy v. Ratta","cite":"292 U.S. 263","y":1934,"id":"scdb/1933-157","sc":1,"sum":"(1) That the matter in controversy did not embrace the right to restrain enforcement of the law by other officers in other places in the State, and that the collateral effect of the decree, by virtue of stare decisis, upon other and distinct controversies with other officers, could not be considered in ascertaining whether the jurisdictional amount was involved, even though their decision might turn on the same …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"6"}},{"t":"case","label":"Merch. Heat & Light Co. v. J.B. Clow & Sons","cite":"204 U.S. 286","y":1907,"id":"scdb/1906-183","sc":1,"sum":"While a non-resident defendant corporation may not lose its right of objecting to the jurisdiction of the court on the ground of insufficient service of process by pleading to the merits pursuant to order of the court after objections overruled, it does waive its objections and submits to the jurisdiction if it also sets up a counterclaim even though it be one arising wholly out of the transaction sued upon by …","sumSrc":"Headnote (U.S. Reports)","by":{"2":"11"}},{"t":"case","label":"Michigan v. Bay Mills Indian Cmty.","cite":"572 U.S. 782","y":2014,"id":"2013/12-515","sc":1,"op":1,"sum":"The Court held that Indian tribes have sovereign immunity that can only be revoked by Congress, and that the immunity extends to their commercial activities, even if they are not on their protected land.","sumSrc":"Oyez","by":{"2":"15"}},{"t":"case","label":"Pension Benefit Guar. Corp. v. LTV Corp.","cite":"496 U.S. 633","y":1990,"id":"1989/89-390","sc":1,"op":1,"sum":"The PBGC's restoration decision was not arbitrary and capricious or contrary to law under § 706(2)(A).","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"15"}},{"t":"case","label":"Soper v. Kahn","cite":"568 F. Supp. 398","y":1983,"court":"D. Md.","url":"https://www.courtlistener.com/c/F.%20Supp./568/398/","by":{"2":"15"}},{"t":"case","label":"Star Athletica, L.L.C. v. Varsity Brands, Inc.","cite":"137 S. Ct. 1002","y":2017,"id":"2016/15-866","sc":1,"op":1,"sum":"The Court determined that the test for deciding whether a feature of a “useful article” is copyrightable under the Copyright Act is whether the feature can be perceived as a two- or three-dimensional artwork that is separable from the useful article and if it would be a protectable pictorial, graphical, or sculptural work on its own.","sumSrc":"Oyez","by":{"2":"15"}},{"t":"case","label":"Tex. & Pac. Ry. Co. v. Eastin","cite":"214 U.S. 153","y":1909,"id":"scdb/1908-155","sc":1,"sum":"The right of a defendant who has petitioned for removal of a case to the Federal court cannot be extended beyond what is necessary to defend the case; he cannot deny the jurisdiction after invoking it for affirmative relief.","sumSrc":"Headnote (U.S. Reports)","by":{"2":"11"}},{"t":"case","label":"Texas ex rel. Bd. of Regents v. Walker","cite":"142 F.3d 813","y":1998,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/142/813/","op":1,"by":{"2":"14"}},{"t":"case","label":"United Benefit Life Ins. Co. v. U.S. Life Ins. Co.","cite":"36 F.3d 1063","y":1994,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/36/1063/","op":1,"by":{"2":"14"}},{"t":"case","label":"Zuber v. Allen","cite":"396 U.S. 168","y":1969,"id":"1969/25","sc":1,"sum":"Respondent Vermont dairy farmers (\"country\" milk producers) brought this action to invalidate the so-called farm location differential provided for by order of the Secretary of Agriculture as contrary to the Agricultural Marketing Agreement Act of 1937. The effect of the order is to require milk distributors to pay milk producers situated close to milk marketing areas (\"nearby\" farmers) higher prices than are paid …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"15"}},{"t":"law","label":"Leahy-Smith America Invents Act, Pub. L. No. 112-29","url":"https://www.govinfo.gov/link/plaw/112/public/29","by":{"2":"9"}},{"t":"usc","label":"26 U.S.C. § 11","url":"https://www.law.cornell.edu/uscode/text/26/11","by":{"2":"9"}},{"t":"usc","label":"26 U.S.C. § 1361","url":"https://www.law.cornell.edu/uscode/text/26/1361","by":{"2":"9"}},{"t":"usc","label":"28 U.S.C. § 1331","url":"https://www.law.cornell.edu/uscode/text/28/1331","stext":{"head":"§1331. Federal question","paras":[[0,"The district courts shall have original jurisdiction of all civil actions arising under the Constitution, laws, or treaties of the United States."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1331?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§1331. Federal question","tname":"Judiciary and Judicial Procedure","by":{"2":"13"}}]};